{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"title: HDSI Postdoctoral Fellowship Program\n"},"line_number":2,"absolute_offset":4,"submatches":[{"match":{"text":"HDS"},"start":7,"end":10}]}}
{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"The next HDSI Postdoctoral Fellow competition will open in September 2025, please subscribe to our newsletter to remain informed.\n"},"line_number":5,"absolute_offset":69,"submatches":[{"match":{"text":"HDS"},"start":9,"end":12}]}}
{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"The Harvard Data Science Initiative (HDSI) is seeking applications for its flagship Harvard Data Science Postdoctoral Fellows Program for the 2025-2026 academic year. The normal duration of the Fellowship is two years. Fellows will receive a generous salary as well as an annual allocation for research and travel expenses.\n"},"line_number":9,"absolute_offset":236,"submatches":[{"match":{"text":"HDS"},"start":37,"end":40}]}}
{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"The HDSI Postdoctoral Fellows Program will support outstanding researchers whose interests relate to the following themes:\n"},"line_number":17,"absolute_offset":1242,"submatches":[{"match":{"text":"HDS"},"start":4,"end":7}]}}
{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"- A cover letter and up to five (and at least two) Harvard faculty members from across the university with whom the applicant would like to work. Candidates are not expected to already have formed a relationship with prospective mentors, and should not contact faculty directly prior to submission of application. The HDSI will reach out to faculty mentors for the most meritorious applications.\n"},"line_number":45,"absolute_offset":3619,"submatches":[{"match":{"text":"HDS"},"start":318,"end":321}]}}
{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"- The HDSI is committed to supporting research that promotes fair and responsible data science. We ask that you submit an impact statement (<500 words) that speaks to the ethical issues and potential societal impact of your proposed work, areas of interest, or data science more broadly. This requirement is modeled in part on a similar requirement by NeurIPS, and applicants may find this guide helpful in thinking about how to write this statement.\n"},"line_number":51,"absolute_offset":4291,"submatches":[{"match":{"text":"HDS"},"start":6,"end":9}]}}
{"type":"match","data":{"path":{"text":"datascience.harvard.edu/HDSI Postdoctoral Fellowship Program.txt"},"lines":{"text":"Applicants should be intellectually curious researchers at an early stage of their scholarly career. Applicants are required to have a doctorate in a related area by the expected start date of their fellowship. Applicants should have demonstrated a capacity for independent work, and will be expected to engage with researchers and faculty and participate in activities convened by the HDSI.\n"},"line_number":59,"absolute_offset":5105,"submatches":[{"match":{"text":"HDS"},"start":386,"end":389}]}}
